# ----------------------------- Configuración ---------------------------------
def _has_secrets():
    try:
        return "gcp_service_account" in st.secrets
    except Exception:
        return False

CONFIG_OK = _has_secrets()
FOLDER_MIME = "application/vnd.google-apps.folder"
RAIZ = "📁  Raíz de la unidad"
NUEVA = "➕  Crear carpeta nueva…"

def _sa_email():
    try:
        return st.secrets["gcp_service_account"]["client_email"]
    except Exception:
        return ""

def _access_code():
    try:
        return st.secrets.get("drive", {}).get("access_code", "")
    except Exception:
        return ""

@st.cache_resource(show_spinner=False)
def get_drive():
    from google.oauth2 import service_account
    from googleapiclient.discovery import build
    info = dict(st.secrets["gcp_service_account"])
    creds = service_account.Credentials.from_service_account_info(
        info, scopes=["https://www.googleapis.com/auth/drive"])
    return build("drive", "v3", credentials=creds, cache_discovery=False)

@st.cache_data(ttl=120, show_spinner=False)
def cached_drives():
    svc = get_drive()
    out, tok = [], None
    while True:
        r = svc.drives().list(pageSize=100, fields="nextPageToken, drives(id,name)",
                              pageToken=tok).execute()
        out += r.get("drives", []); tok = r.get("nextPageToken")
        if not tok: break
    return out

@st.cache_data(ttl=45, show_spinner=False)
def cached_folders(drive_id):
    svc = get_drive()
    r = svc.files().list(
        q=f"'{drive_id}' in parents and mimeType='{FOLDER_MIME}' and trashed=false",
        corpora="drive", driveId=drive_id, includeItemsFromAllDrives=True,
        supportsAllDrives=True, orderBy="name", pageSize=200,
        fields="files(id,name)").execute()
    return r.get("files", [])

def find_or_create_folder(svc, name, parent_id, drive_id):
    safe = name.replace("'", " ").strip() or "Sin nombre"
    q = (f"mimeType='{FOLDER_MIME}' and trashed=false and name='{safe}' "
         f"and '{parent_id}' in parents")
    res = svc.files().list(q=q, corpora="drive", driveId=drive_id,
        includeItemsFromAllDrives=True, supportsAllDrives=True,
        fields="files(id,name)").execute()
    hits = res.get("files", [])
    if hits: return hits[0]["id"]
    meta = {"name": safe, "mimeType": FOLDER_MIME, "parents": [parent_id]}
    return svc.files().create(body=meta, supportsAllDrives=True, fields="id").execute()["id"]

# ---- compartir (agregar acceso + mail) ----
def share_one(svc, fid, email):
    body = {"type": "user", "role": "writer", "emailAddress": email}
    try:
        svc.permissions().create(fileId=fid, body=body, sendNotificationEmail=True,
                                 supportsAllDrives=True, fields="id").execute()
        return True
    except Exception:
        try:  # reintento sin mail (igual queda el acceso)
            svc.permissions().create(fileId=fid, body=body, sendNotificationEmail=False,
                                     supportsAllDrives=True, fields="id").execute()
            return True
        except Exception:
            return False

def share_targets(svc, ids, emails):
    ok = True
    for fid in ids:
        for em in emails:
            if not share_one(svc, fid, em):
                ok = False
    return ok

# ---- subir desde la compu ----
def upload_one(svc, file, parent_id):
    from googleapiclient.http import MediaIoBaseUpload
    mt = file.type or mimetypes.guess_type(file.name)[0] or "application/octet-stream"
    media = MediaIoBaseUpload(io.BytesIO(file.getvalue()), mimetype=mt,
                              resumable=True, chunksize=5 * 1024 * 1024)
    return svc.files().create(body={"name": file.name, "parents": [parent_id]},
        media_body=media, supportsAllDrives=True, fields="id,webViewLink").execute()

# ---- copiar desde Google Drive ----
def parse_drive_id(url):
    url = (url or "").strip()
    for pat in (r"/folders/([A-Za-z0-9_-]+)", r"/file/d/([A-Za-z0-9_-]+)",
                r"[?&]id=([A-Za-z0-9_-]+)", r"/d/([A-Za-z0-9_-]+)"):
        m = re.search(pat, url)
        if m: return m.group(1)
    if re.fullmatch(r"[A-Za-z0-9_-]{20,}", url): return url
    return None

def list_children(svc, fid):
    items, tok = [], None
    while True:
        r = svc.files().list(q=f"'{fid}' in parents and trashed=false",
            fields="nextPageToken, files(id,name,mimeType)",
            includeItemsFromAllDrives=True, supportsAllDrives=True,
            pageSize=1000, pageToken=tok).execute()
        items += r.get("files", []); tok = r.get("nextPageToken")
        if not tok: break
    return items

def copy_file(svc, fid, name, dest):
    return svc.files().copy(fileId=fid, body={"name": name, "parents": [dest]},
        supportsAllDrives=True, fields="id,webViewLink").execute()

def copy_folder_recursive(svc, src_id, src_name, dest_parent, drive_id, counter, status):
    new_folder = find_or_create_folder(svc, src_name, dest_parent, drive_id)
    for it in list_children(svc, src_id):
        if it["mimeType"] == FOLDER_MIME:
            copy_folder_recursive(svc, it["id"], it["name"], new_folder, drive_id, counter, status)
        else:
            try:
                copy_file(svc, it["id"], it["name"], new_folder); counter["n"] += 1
                status.update(label=f"Copiando… {counter['n']} archivo(s)")
            except Exception as e:
                counter["err"].append((it["name"], str(e)))
    return new_folder

# ----------------------------- Acceso ----------------------------------------
if not CONFIG_OK:
    st.markdown('<div class="warn">⚙️ <b>Modo vista previa.</b> Todavía no está '
                'conectada al Drive (falta la clave de servicio). Así se ve para quien la use.</div>',
                unsafe_allow_html=True)

def gate():
    if not CONFIG_OK: return True
    code = _access_code()
    if not code or st.session_state.get("ok_code"): return True
    st.markdown("#### 🔑 Ingresá el código del equipo")
    c = st.text_input("Código", type="password", label_visibility="collapsed",
                      placeholder="Código de acceso")
    if st.button("Entrar"):
        if c == code: st.session_state["ok_code"] = True; st.rerun()
        else: st.error("Código incorrecto.")
    return False

def resolve_dest(svc, drive_id, carpeta, folders_map, nueva):
    if carpeta == RAIZ: return drive_id
    if carpeta == NUEVA:
        if not (nueva or "").strip():
            st.error("Escribí el nombre de la carpeta nueva."); return None
        return find_or_create_folder(svc, nueva.strip(), drive_id, drive_id)
    return folders_map.get(carpeta, drive_id)

def selected_people():
    emails, names = [], []
    for p in EQUIPO:
        if st.session_state.get("chk_" + p["nombre"]):
            emails += p["emails"]; names.append(p["nombre"])
    # dedup conservando orden
    seen = set(); dedup = [e for e in emails if not (e in seen or seen.add(e))]
    return dedup, names

if gate():
    with st.container(border=True):
        st.text_input("Tu nombre (opcional)", key="nombre", placeholder="Ej.: María González")

        # ---------- DESTINO: unidad + carpeta ----------
        st.markdown("##### 1 · ¿A dónde lo subimos?")
        drive_id = None; carpeta = RAIZ; folders_map = {}; nueva = ""
        if CONFIG_OK:
            try:
                drives = cached_drives()
            except Exception as e:
                drives = []; st.error(f"No pude leer las unidades: {e}")
            if not drives:
                st.markdown('<div class="warn">La cuenta de servicio todavía no es miembro de '
                            'ninguna Unidad compartida. Agregala (como <b>Administrador de contenido</b>) '
                            'en las unidades que quieras que aparezcan acá.</div>', unsafe_allow_html=True)
            else:
                dmap = {d["name"]: d["id"] for d in drives}
                unidad = st.selectbox("Unidad", list(dmap.keys()))
                drive_id = dmap[unidad]
                folders = cached_folders(drive_id)
                folders_map = {f["name"]: f["id"] for f in folders}
                carpeta = st.selectbox("Carpeta", [RAIZ] + list(folders_map.keys()) + [NUEVA])
                if carpeta == NUEVA:
                    nueva = st.text_input("Nombre de la carpeta nueva", placeholder="Ej.: Podcast octubre")
        else:
            st.selectbox("Unidad", ["(se llenan cuando esté conectada)"], disabled=True)
            st.selectbox("Carpeta", [RAIZ, NUEVA], disabled=True)

        # ---------- COMPARTIR CON (checklist) ----------
        st.markdown("##### 2 · ¿Compartir con alguien? (les llega un mail y quedan con acceso)")
        cols = st.columns(len(EQUIPO))
        for i, p in enumerate(EQUIPO):
            with cols[i]:
                st.checkbox(p["nombre"], key="chk_" + p["nombre"])

    st.markdown("##### 3 · Subí tu contenido")
    tab1, tab2 = st.tabs(["📁  Desde mi computadora", "☁️  Desde mi Google Drive"])

    # -------- TAB 1: desde la compu --------
    with tab1:
        files = st.file_uploader("Arrastrá tus archivos (podés soltar varios)",
                                 accept_multiple_files=True)
        disabled = (not CONFIG_OK) or (drive_id is None) or (not files)
        if st.button("Subir a esta carpeta", disabled=disabled, key="btn1"):
            svc = get_drive()
            dest = resolve_dest(svc, drive_id, carpeta, folders_map, nueva)
            if dest:
                prog = st.progress(0.0, text="Subiendo…"); oks = []; ids = []
                for i, f in enumerate(files, start=1):
                    try:
                        r = upload_one(svc, f, dest)
                        oks.append((f.name, r.get("webViewLink"))); ids.append(r["id"])
                    except Exception as e:
                        st.error(f"❌ «{f.name}»: {e}")
                    prog.progress(i/len(files), text=f"Subiendo… {i}/{len(files)}")
                prog.empty()
                if oks:
                    st.success(f"¡Listo! Subiste {len(oks)} archivo(s). 🙌")
                    for nm, link in oks:
                        st.markdown(f'<div class="ok">✔️ <a href="{link}" target="_blank">{nm}</a></div>'
                                    if link else f'<div class="ok">✔️ {nm}</div>', unsafe_allow_html=True)
                    emails, names = selected_people()
                    if emails:
                        share_ids = [dest] if carpeta == NUEVA else ids
                        share_targets(svc, share_ids, emails)
                        st.info("📧 Compartido con: " + ", ".join(names))
        if disabled:
            _f = []
            if not CONFIG_OK: _f.append("conectar el Drive")
            elif drive_id is None: _f.append("elegir una unidad")
            if not files: _f.append("arrastrar al menos un archivo")
            if _f: st.markdown('<div class="miss">Para subir, falta ' + " y ".join(_f) + '.</div>', unsafe_allow_html=True)

    # -------- TAB 2: desde Drive --------
    with tab2:
        sa = _sa_email()
        st.markdown('<div class="hintbox">Pegá el link de una carpeta o archivo de tu Google Drive y se copia enterito a la unidad. Antes, en tu Drive: <b>Compartir</b> → agregá este correo como <b>Lector</b> (o poné <b>“Cualquiera con el enlace”</b>). Copialo con el botón 👇</div>', unsafe_allow_html=True)
        if sa:
            st.code(sa, language=None)
        link = st.text_input("Link de Google Drive",
                             placeholder="https://drive.google.com/drive/folders/…")
        disabled2 = (not CONFIG_OK) or (drive_id is None) or (not link)
        if st.button("Copiar a esta carpeta", disabled=disabled2, key="btn2"):
            fid = parse_drive_id(link)
            if not fid:
                st.error("No pude leer el link. Copiá el enlace completo.")
            else:
                svc = get_drive()
                dest = resolve_dest(svc, drive_id, carpeta, folders_map, nueva)
                if dest:
                    try:
                        meta = svc.files().get(fileId=fid, fields="id,name,mimeType",
                                               supportsAllDrives=True).execute()
                        counter = {"n": 0, "err": []}; made_id = None
                        if meta["mimeType"] == FOLDER_MIME:
                            with st.status(f"Copiando «{meta['name']}»…", expanded=False) as status:
                                made_id = copy_folder_recursive(svc, fid, meta["name"], dest, drive_id, counter, status)
                                status.update(label=f"¡Listo! {counter['n']} archivo(s).", state="complete")
                            st.success(f"Copié «{meta['name']}» ({counter['n']} archivos). 🙌")
                        else:
                            r = copy_file(svc, fid, meta["name"], dest); made_id = r["id"]
                            st.success("¡Copiado! 🙌")
                            st.markdown(f'<div class="ok">✔️ <a href="{r.get("webViewLink")}" '
                                        f'target="_blank">{meta["name"]}</a></div>', unsafe_allow_html=True)
                        if counter["err"]:
                            st.warning(f"{len(counter['err'])} archivo(s) no se pudieron copiar.")
                        emails, names = selected_people()
                        if emails and made_id:
                            share_targets(svc, [made_id], emails)
                            st.info("📧 Compartido con: " + ", ".join(names))
                    except Exception as e:
                        msg = str(e)
                        if any(k in msg for k in ("404", "notFound", "403")):
                            st.error("No pude acceder a ese link. Revisá que lo hayas compartido "
                                     + (f"con `{sa}` " if sa else "con el email de la app ")
                                     + "o puesto en “Cualquiera con el enlace”.")
                        else:
                            st.error(f"Problema al copiar: {e}")
        if disabled2:
            _g = []
            if not CONFIG_OK: _g.append("conectar el Drive")
            elif drive_id is None: _g.append("elegir una unidad")
            if not link: _g.append("pegar el link de Drive")
            if _g: st.markdown('<div class="miss">Para copiar, falta ' + " y ".join(_g) + '.</div>', unsafe_allow_html=True)

st.markdown('<div style="text-align:center;color:#b09a7f;font-size:.8rem;margin-top:2.2rem">'
            'René Boiero · buzón de archivos</div>', unsafe_allow_html=True)
